CREATE TABLE IF NOT EXISTS clin_files ( id INTEGER PRIMARY KEY AUTOINCREMENT, patient_id INTEGER NOT NULL REFERENCES clin_patients(id) ON DELETE CASCADE, kv_key TEXT NOT NULL, file_name TEXT NOT NULL, content_type TEXT NOT NULL, size_bytes INTEGER NOT NULL, ai_summary TEXT, uploaded_by INTEGER, uploaded_by_name TEXT, created_at TEXT NOT NULL DEFAULT (datetime('now')) ); CREATE INDEX IF NOT EXISTS idx_clin_files_patient ON clin_files(patient_id, created_at); CREATE TABLE IF NOT EXISTS clin_reports ( id INTEGER PRIMARY KEY AUTOINCREMENT, patient_id INTEGER NOT NULL REFERENCES clin_patients(id) ON DELETE CASCADE, template TEXT NOT NULL, report_no TEXT, title TEXT, report_date TEXT NOT NULL, valid_until TEXT, status TEXT NOT NULL DEFAULT 'draft', data_json TEXT NOT NULL DEFAULT '{}', clinician TEXT, qualification TEXT, rci_no TEXT, ai_used INTEGER NOT NULL DEFAULT 0, created_by INTEGER, created_by_name TEXT, created_at TEXT NOT NULL DEFAULT (datetime('now')), updated_at TEXT NOT NULL DEFAULT (datetime('now')), finalized_at TEXT ); CREATE INDEX IF NOT EXISTS idx_clin_reports_patient ON clin_reports(patient_id, report_date); CREATE INDEX IF NOT EXISTS idx_clin_reports_no ON clin_reports(report_no); CREATE TABLE IF NOT EXISTS clin_plans ( id INTEGER PRIMARY KEY AUTOINCREMENT, patient_id INTEGER NOT NULL REFERENCES clin_patients(id) ON DELETE CASCADE, report_id INTEGER, title TEXT NOT NULL, sessions_count INTEGER NOT NULL, minutes INTEGER, per_week INTEGER, start_date TEXT, focus TEXT, status TEXT NOT NULL DEFAULT 'draft', plan_json TEXT NOT NULL DEFAULT '{}', progress_json TEXT NOT NULL DEFAULT '{}', ai_used INTEGER NOT NULL DEFAULT 0, created_by INTEGER, created_by_name TEXT, created_at TEXT NOT NULL DEFAULT (datetime('now')), updated_at TEXT NOT NULL DEFAULT (datetime('now')) ); CREATE INDEX IF NOT EXISTS idx_clin_plans_patient ON clin_plans(patient_id);
